static void Lighting(){foreach(var l in UnityEngine.Object.FindObjectsByType<Light>(FindObjectsSortMode.None))if(l.type==LightType.Directional)l.intensity=1f;RenderSettings.ambientIntensity=.7f;foreach(var v in UnityEngine.Object.FindObjectsByType<Volume>(FindObjectsSortMode.None)){if(!v.sharedProfile)continue;var p=UnityEngine.Object.Instantiate(v.sharedProfile);AssetDatabase.CreateAsset(p,"Assets/CityForge/Art/Environment/MeadowNativeURP/Showcase/ValleyVolume.asset");v.sharedProfile=p;if(p.TryGet<ColorAdjustments>(out var col)){col.postExposure.Override(-.3f);col.saturation.Override(-5f);EditorUtility.SetDirty(p);}}foreach(var t in UnityEngine.Object.FindObjectsByType<Transform>(FindObjectsInactive.Include,FindObjectsSortMode.None))GameObjectUtility.RemoveMonoBehavioursWithMissingScript(t.gameObject);AssetDatabase.SaveAssets();EditorSceneManager.SaveScene(UnityEngine.SceneManagement.SceneManager.GetActiveScene());}
